const home = `<section class="hero" aria-labelledby="home-title"><div class="hero-field" data-field="hero" data-field-avoid=".hero-text" aria-hidden="true"></div>${pause}<div class="hero-inner"><div class="hero-text"><p class="eyebrow">With UXPA Seattle</p><h1 id="home-title">AI-First<br>Design<br>Workshop</h1><p class="hero-when"><time datetime="2026-11-19T17:30:00-08:00">Thursday, Nov 19, 2026</time><br>5:30 to 8:30 PM PT · Seattle</p><p class="hero-note">A hands-on evening for designers. Bring your laptop, try a few small tasks, and build alongside each other.</p><div class="actions"><a class="button" href="${u('get-ready/')}">Get ready <span aria-hidden="true">↗</span></a><a class="text-link" href="${u('tonight/')}">See tonight's draft guide →</a></div></div></div></section>
<div class="wrap">
<section class="section" aria-labelledby="make"><div class="section-head"><h2 id="make">What we'll try together</h2><p>Work in your own fork of <a href="https://github.com/h16nning/skola">Skola</a>, an open-source, local-first flashcard app. The goal is a meaningful redesign or feature, a narrated demo, and a repo link you can put in your portfolio. We'll build alongside each other, with pauses for help.</p></div><div class="capability-grid"><div class="capability"><span class="number">01</span><h3>Make a quick redesign</h3><p>Improve a real screen. Mark up a screenshot to show the change, then make it work in the code.</p></div><div class="capability"><span class="number">02</span><h3>Add a useful feature</h3><p>Go beyond a visual edit. Make a small feature, try it yourself, and check the states that matter.</p></div><div class="capability"><span class="number">03</span><h3>Compare three designs</h3><p>Explore visual alternatives in parallel. Keep the same task and compare different ways to support it.</p></div></div><p class="small muted" style="margin-top:30px">Also planned: narrated videos, hands-on Computer Use, fictional research synthesis, and a personal taste automation. Skola is the shared project. Each task will have its own starting point. The fictional brief, detailed timing and publishing recipe are still draft.</p></section>
<section class="section" aria-labelledby="clock"><div class="section-head"><h2 id="clock">Tonight's clock</h2><p>All times are Pacific. We'll build together first, then make room for your own projects.</p></div><ol class="timeline"><li><time datetime="2026-11-19T17:30:00-08:00">5:30 PM</time><strong>Arrive</strong><small>Check in, food, conversation</small></li><li><time datetime="2026-11-19T17:50:00-08:00">5:50 PM</time><strong>Meet each other</strong><small>Names and what you want to try</small></li><li><time datetime="2026-11-19T18:00:00-08:00">6:00 PM</time><strong>Get oriented</strong><small>The tools and ground rules</small></li><li><time datetime="2026-11-19T18:10:00-08:00">6:10 PM</time><strong>Build together</strong><small>Small tasks, with pauses for help</small></li><li><time datetime="2026-11-19T19:10:00-08:00">7:10 PM</time><strong>Make it yours</strong><small>Free work in pairs</small></li><li><time datetime="2026-11-19T20:00:00-08:00">8:00 PM</time><strong>Show and tell</strong><small>A result and one decision</small></li><li><time datetime="2026-11-19T20:20:00-08:00">8:20 PM</time><strong>Keep going</strong><small>Questions and take-home. End at 8:30.</small></li></ol></section>
<section class="section" aria-labelledby="hosts"><div class="section-head"><h2 id="hosts">Hosted by UXPA Seattle, with Eli King and Thoa Nguyen</h2><p>We're sharing how we work on our own teams. There's no single right way to design with AI.</p></div><div class="hosts"><div class="host"><h3>Eli King</h3><p>A product designer working on AI experiences in VS Code and GitHub Copilot. He prototypes in code and contributes to open source VS Code.</p></div><div class="host"><h3>Thoa Nguyen</h3><p>A product designer working on how developers build AI agents. She experiments in code and builds agents to review her designs.</p></div></div><p class="small muted" style="margin-top:32px">The address is on your Luma ticket. <a href="https://luma.com/hw3533y5">View the event on Luma</a>.</p></section>
<section class="section" aria-labelledby="your-next"><div class="section-head"><h2 id="your-next">Everything for the evening</h2><p>Start with setup. The guide and glossary will be here when you need them.</p></div><div class="next-grid">${next('Get ready', 'The setup, permissions and costs.', 'get-ready/')}${next('Tonight', 'Draft task cards with prompts to copy.', 'tonight/')}${next('Words to know', 'GitHub and AI, in plain words.', 'words/')}${next('Keep going', 'The password-protected take-home.', 'keep-going/')}${next('Skills', 'Reusable workflows for your own projects.', 'skills/')}</div></section>
</div>`;

const ready = hero('Before Thursday', 'Get ready', 'Bring a personal laptop and your charger. You can do these checks ahead of time, or ask for help at check-in.') + layout([
  ['Workshop settings', 'workshop-settings'], ['VS Code Insiders', 'insiders'], ['GitHub account', 'github-account'], ['Your free month', 'free-month'], ['Try dictation', 'dictation'], ['Git', 'git'], ['Node and packages', 'node'], ['Screenshot and mark up', 'screenshot-markup'], ['Computer Use', 'computer-use'], ['Mode and permissions', 'permissions'], ['Controls', 'controls'], ['Spending', 'spending'], ['What is public', 'public'],
], `
<section id="workshop-settings"><div class="step-heading"><span class="step-number">01</span><h2>Workshop settings</h2></div>${checked}<p>These two experimental settings make Computer Use and Send Later available. They do not approve tools, start an automation or purchase anything. Install Insiders below if you haven't yet, then return here.</p><p>Use a backed-up merge in your <strong>Default Profile</strong>. Read the steps below before pasting; do not replace your whole settings file.</p>${promptBlock('workshop-settings-entries', workshopEntries, 'Entries for existing settings')}<p class="small muted">Copy the entries above into your existing outer braces. For a blank file or <code>{}</code>, use the complete snippet below. <a href="${u('get-ready/workshop-settings.jsonc')}" download>Download the settings file</a>.</p><details><summary>Complete snippet for an empty settings file</summary>${promptBlock('workshop-settings-complete', workshopSettings, 'Complete settings snippet')}</details><h3>Add them without losing your settings</h3><ol><li>Open the Command Palette: <strong>Shift+Command+P</strong> on Mac or <strong>Ctrl+Shift+P</strong> on Windows. Run <strong>Profiles: Switch Profile</strong>, note your current profile, then choose <strong>Default</strong>.</li><li>Run <strong>Preferences: Open User Settings (JSON)</strong>. Choose the user file, not Default Settings or Workspace Settings.</li><li>Save a complete local backup as <code>workshop-settings-before.txt</code>, outside your repo. Don't share it; settings can contain private information.</li><li>Paste the two entries inside the existing outer <code>{ }</code>. Put a comma after the preceding entry if it doesn't already have one. Keep the comma between the two new entries. Don't add another pair of braces.</li><li>If a key already exists, change its value to <code>true</code> instead of adding it twice. Note its previous value, or that it was absent.</li><li>Save with <strong>Command+S</strong> or <strong>Ctrl+S</strong>. Resolve any settings warning, save your work, then quit and reopen Insiders for Computer Use.</li></ol><p class="small muted">A separate profile is not the undo route: the Agents window uses the Default Profile, while plugin access, saved automations and OS permissions need their own cleanup.</p><h3 id="undo-setup">Undo it</h3><ol><li>Stop workshop runs. Cancel pending Send Later requests in <strong>Automations</strong>, then disable or delete the workshop automation. Turning off a setting does not cancel accepted schedules.</li><li>Run <code>/computer off</code>, restore its previous setting value, and restart Insiders.</li><li>Revoke the related OS permissions if you no longer want access.</li><li>In the same Default Profile user file, restore each value you changed. Delete only entries that were absent before and fix adjacent commas. Restore the whole backup only if no later edits would be lost.</li><li>In <strong>Customizations > Plugins</strong>, remove the workshop plugin if you don't want it. Keep your earlier plugins and sources.</li></ol>${docs([['User settings', DOCS.settingsGuide], ['Agents-window configuration', DOCS.agentsConfiguration], ['Manage automations', DOCS.automations]])}</section>
<section id="insiders"><div class="step-heading"><span class="step-number">02</span><h2>Install VS Code Insiders</h2></div><p>Tonight uses <strong>VS Code Insiders</strong>, not the regular download linked on Luma. Insiders gets new builds frequently. Both versions can live side by side.</p><p><a class="button" href="${DOCS.insiders}">Download Insiders</a></p><p>Choose your operating system, install it, and open it once. Keep your existing editor if you already use one.</p>${detail('Adds a separate app for editing files and working with agents. Opening a folder lets the app read that project; review workspace trust before allowing code to run.', 'Quit Insiders and uninstall the app. Your project files stay where you saved them. Settings and extensions may remain unless you also remove their data.')} ${docs([['Install and download', DOCS.insiders], ['Uninstall VS Code', DOCS.uninstall]])}</section>
<section id="github-account"><div class="step-heading"><span class="step-number">03</span><h2>Sign in to a personal GitHub account</h2></div><p>In Insiders, open the Accounts menu and sign in to GitHub for Copilot. Use a personal account to make your own ${term('fork', 'fork')} of the workshop project. If you need one, <a href="${DOCS.signup}">create a GitHub account</a>.</p><p>Check that the account name is the one you want to use before redeeming your code. Don't choose an additional paid plan during setup.</p>${detail('Connects VS Code to the GitHub account you approve. Copilot requests use that account\'s access and usage allowance.', 'Use the Accounts menu to sign out. This does not cancel a subscription or delete your GitHub account. Manage any plan separately in GitHub settings.')} ${docs([['Set up Copilot in VS Code', DOCS.setup], ['Manage your plan', DOCS.plan]])}</section>
<section id="free-month"><div class="step-heading"><span class="step-number">04</span><h2>Your free month of GitHub Copilot Max</h2></div><p>Every attendee gets a <strong>free month of GitHub Copilot Max</strong>. We'll help you redeem your personal code at check-in. Keep your code private.</p><div class="note"><p><strong>Redemption details are coming.</strong> The code entry steps, any card requirement, renewal date and cancellation steps for this offer still need confirmation. We'll check them with you before you accept the offer.</p></div><p>GitHub's standard Max plan currently costs <strong>$100 USD a month</strong> and includes <strong>20,000 AI credits</strong>. One credit is one cent. The total includes a variable flex allotment; check the current terms when you redeem.</p>${detail('Redeeming the offer changes Copilot access on the account you choose. Read the actual offer terms before confirming.', 'Use GitHub\'s plan settings to manage or cancel a plan. The exact cancellation route and renewal terms for these promotional codes are still being confirmed. Uninstalling VS Code is not a cancellation.')} ${docs([['Max pricing and credits', DOCS.billing], ['Plan and cancellation settings', DOCS.plan]])}</section>
<section id="dictation"><div class="step-heading"><span class="step-number">05</span><h2>Try dictation once</h2></div><p>On an Apple silicon Mac or Windows x64 or Arm64 laptop, select the microphone in the chat input. First use downloads an on-device speech model and asks for microphone access.</p><p>Say: <em>Make the heading a little smaller.</em> Stop the microphone and check the text. ${term('dictation', 'Dictation')} does not send the prompt until you choose to send it. You can delete this test text.</p><p>Audio recognition runs on-device by default on these desktop systems. Optional transcript cleanup sends the text to a model. Turn off optional transcript cleanup in Settings if you don't want that. Intel Mac? Typing is fine; you don't need an extra voice extension for tonight.</p>${detail('Downloads a speech-recognition model and gives VS Code microphone access. Model-based transcript cleanup is a separate setting from on-device audio recognition.', 'Stop dictation, turn off built-in dictation in Settings, and revoke VS Code microphone access in your system privacy settings if you no longer want it. Disabling dictation does not delete the downloaded model.')} ${docs([['Dictation, privacy and supported platforms', DOCS.voice]])}</section>
<section id="git"><div class="step-heading"><span class="step-number">06</span><h2>Git for your own fork</h2></div><p>You need a personal GitHub sign-in and Git to work in your own ${term('fork', 'fork')} of Skola. We will make the folder and clone your fork from VS Code on Mac and Windows.</p><h3>Mac</h3><p>In VS Code, open Terminal > New Terminal and check:</p>${promptBlock('git-version', 'git --version', 'Terminal command')}<p>If Git is missing, macOS may offer Command Line Tools. Review that developer-tools download before installing. It includes more than Git.</p><h3>Windows</h3><p>Install <a href="${DOCS.gitWindows}">Git for Windows</a>, review the installer choices, then reopen Insiders and run the same check.</p>${detail('Adds Git, which saves history and clones your repository. macOS Command Line Tools also includes other developer tools; Git for Windows can add Git Bash and shell integration.', 'Windows: remove Git in Settings > Apps > Installed apps. On Mac, do not remove shared developer tools that other apps use. If you installed them only for the workshop, ask for help before removing the package.')}<div class="note"><p><strong>Nothing goes to the original Skola project.</strong> No PRs, issues, comments or stars from the workshop. A fork PR can default to upstream, so check the base repository every time: it must be your own fork.</p></div>${docs([['Install Git', DOCS.git], ['Skola source, read-only reference', DOCS.skola]])}</section>
<section id="node"><div class="step-heading"><span class="step-number">07</span><h2>Node and the project packages</h2></div><p>Install the <strong>current LTS</strong> from <a href="${DOCS.node}">nodejs.org</a>. Node runs the project's development tools; the installer also provides npm and npx. If you already manage Node versions, keep that setup and select its current LTS instead of adding a second installation.</p><ol><li><strong>Mac:</strong> select macOS and the LTS installer (<code>.pkg</code>) on nodejs.org. Run it and review the installer prompts.</li><li><strong>Windows:</strong> select Windows and the LTS installer (<code>.msi</code>). Run it and review the installer prompts.</li><li>Quit and reopen Insiders. In Terminal > New Terminal, check both tools:</li></ol>${promptBlock('node-check', 'node --version\nnpm --version', 'Check Node and npm')}<p>We will use pnpm through <code>npx</code>, not Corepack and not a global pnpm install. Skola pins pnpm <strong>10.28.2</strong>.</p><details><summary>Draft: optional, install before you come</summary><p>The Wi-Fi plan is still open. Once you have your own fork in its project folder, the dependency command is:</p>${promptBlock('skola-install', 'npx pnpm@10.28.2 install --frozen-lockfile', 'Install inside your project folder')}<p>Review the download before approving it. If install-script warnings appear, ask for help rather than approving everything. Do not start the app until the checked workshop prep has disabled cloud sync.</p></details>${detail('Node and npm are installed on your computer. Skola\'s packages go into its project folder, about 440 MB in the checked Mac install. npx caches pnpm separately, and package caches can use more space. Windows setup still needs rehearsal.', 'Keep any work you want, then delete only your workshop project folder. Use the cache steps below to remove its npx entry. This does not uninstall Node: on Windows use Installed apps; with a version manager use that manager. A Mac package install has no simple app to drag to the Trash, so do not manually remove a shared runtime without checking what else uses it.')}<h3>Clear the workshop's npx cache</h3><p>List the entries, inspect the one used for pnpm, then remove only that entry. Replace <code>CACHE_KEY</code> with the key shown by the list:</p>${promptBlock('npx-cache', 'npm cache npx ls\nnpm cache npx info CACHE_KEY\nnpm cache npx rm CACHE_KEY', 'Review and remove the npx entry')}<p class="small muted">These are npm's npx-cache commands, not a command to delete your whole npm cache. If your npm version does not support them, use its matching docs or ask for help. Do not clear unrelated entries by guesswork.</p>${docs([['Node LTS download', DOCS.node], ['Node and npm installation', DOCS.nodeInstall], ['npx cache commands', DOCS.npmCache]])}</section>
<section id="screenshot-markup"><h2>Screenshot and mark up</h2>${checked}<p>Try native <strong>Mark Up</strong> in the chat input first. You make the visual mockup; the agent changes the real interface from that image.</p><ol><li>Capture the real interface. Where offered, use <strong>Add Context (+) > Screenshot Window</strong> or <strong>Screenshot App Window...</strong>. You can also use the OS tools below.</li><li>Attach the image to the current chat input: paste with <strong>Command+V</strong> on Mac or <strong>Ctrl+V</strong> on Windows, drop the file, or use <strong>Add Context (+) > Files</strong>. Confirm its thumbnail appears.</li><li>Select the <strong>unsent image</strong>, then <strong>Mark Up</strong>. Use arrows, drawing, text or crop to show your change.</li><li>Select <strong>Done</strong>, then send the image with your request. Ask the agent to change the actual code and inspect the working result.</li></ol><p class="small muted"><strong>Escape applies and finishes markup; it does not discard it.</strong> Select / Move handles added annotations, not the original screenshot's pixels. A cut-and-rearrange workflow still needs checking. Use PNG or JPEG with a model that supports images, and keep private information out.</p><details><summary>If native capture or Mark Up is missing</summary><p><strong>macOS:</strong> use Shift-Command-5 or Shift-Command-4, then edit the thumbnail or open the image in Preview's Markup toolbar. Use SDR / PNG where the format choice is offered.</p><p><strong>Windows:</strong> open Snipping Tool or press Windows logo key + Shift + S. Use its pen, highlighter, shapes and crop. Copy the edited snip with Ctrl+C or save with Ctrl+S.</p><p>Keep an original copy. Paste or attach the edited image, not just its filename. These fallback tools annotate and crop; a layered rearrangement of the original UI is not a checked workshop step.</p></details>${detail('Adds an image to your prompt. Native app-window capture can request screen-recording permission; it does not activate Computer Use or grant app control.', 'Undo marks before finishing, or remove the unsent attachment and attach the original again. Delete only image copies you made. Revoke capture permission separately if you no longer want it.')} ${docs([['Attach images and browser context', DOCS.context], ['Screenshots on Mac', DOCS.macScreenshot], ['Markup in Preview', DOCS.macMarkup], ['Snipping Tool on Windows', DOCS.windowsScreenshot]])}</section>
<section id="computer-use"><h2>Start and stop Computer Use</h2>${checked}<ol><li>After applying the settings and restarting, open a <strong>Copilot</strong> chat on <strong>This Computer</strong>.</li><li>Enter <code>/computer on</code>. First use downloads its plugin. On Mac, choose <strong>Set Up Computer Use</strong> and grant <strong>Accessibility</strong> and <strong>Screen Recording</strong> yourself. Recent macOS versions call the latter <strong>Screen &amp; System Audio Recording</strong>.</li><li>Use only the agreed harmless app task and public practice files. Check each access request.</li><li>Enter <code>/computer off</code> to turn it off. Restore the old setting and restart if you no longer want the feature. Remove its OS grants in <strong>System Settings > Privacy &amp; Security</strong> too.</li></ol><p>Computer Use can inspect and interact with desktop apps. Activation persists across chats and also affects Copilot CLI on that computer. Removing the setting alone does not revoke OS access. Windows has its own setup flow and still needs a first-use rehearsal.</p><p><strong>Screenshot markup is not Computer Use.</strong> You draw the mockup yourself. We may install one small tool together in the room; we'll explain the download, permissions and undo steps before you approve it.</p>${docs([['Computer Use setup and off steps', DOCS.computer], ['Computer Use permissions', DOCS.computerPermissions]])}</section>
<section id="permissions"><h2>Mode and permissions</h2>${checked}<p><strong>Interactive</strong>, <strong>Plan</strong> and <strong>Autopilot</strong> are modes in Copilot. Interactive does the task. Plan proposes an approach first; enter <code>/plan</code> and review it. Autopilot keeps working and <strong>auto-approves tools</strong>.</p><p><strong>Manual</strong>, <strong>Assisted</strong> and <strong>Allow all</strong> are permission levels. Manual follows your existing approval rules, so it does not ask before every action. Assisted uses a model to assess calls and asks about those it does not approve. Allow all runs tools without confirmation.</p><p><strong>New Worktree sessions always use Allow all.</strong> A worktree separates files, not access to your machine. None of these modes or levels is a sandbox.</p><p>Start in a regular folder with Manual permissions and use Allow Once where offered. Only choose broader access deliberately. The settings snippet does not choose it for you.</p>${docs([['Approvals and permissions', DOCS.permissions], ['Planning', DOCS.planning]])}</section>
<section id="controls"><h2>Basic controls</h2>${checked}<p>Use the labeled menu choices first. These shortcuts assume default bindings and the current <strong>steer</strong> preference. Your existing settings can differ.</p><dl class="control-list"><div><dt>Send</dt><dd>Starts an idle request. <span>Mac and Windows: Enter.</span></dd></div><div><dt>Add to Queue</dt><dd>Waits until the current response finishes. <span>Mac: Option+Enter. Windows: Alt+Enter, with the steer default.</span></dd></div><div><dt>Steer with Message</dt><dd>Redirects after the current tool finishes. <span>Mac and Windows: Enter, with the steer default.</span></dd></div><div><dt>Stop and Send</dt><dd>Cancels the request and immediately sends your new message. <span>Use the Send dropdown; no dedicated shortcut confirmed.</span></dd></div><div><dt>Stop</dt><dd>Requests cancellation without another message. <span>Mac: Control+Escape. Windows: Alt+Backspace.</span></dd></div><div><dt>Send Later</dt><dd>Schedules one prompt, not a recurring task. <span>Use Send Later... in the Send dropdown or Chat: Send Later... in the palette. No dedicated shortcut.</span></dd></div><div><dt>Edit and resend</dt><dd>Edits an earlier request. Review what will be rewound first; it does not undo external actions. <span>Enter on a focused request, then Enter to resend, on either platform.</span></dd></div><div><dt>Attach a screenshot</dt><dd>Paste the image, drop a file, or use + > Files. Confirm the thumbnail is supported. <span>Mac: Command+V. Windows: Ctrl+V.</span></dd></div><div><dt>Mark Up</dt><dd>Select the unsent image, choose Mark Up, then Done. <span>Enter opens a focused image. Escape applies and finishes markup, not discard.</span></dd></div><div><dt>Switch model</dt><dd>Use the input's model picker. It changes the next request, not the harness. <span>Mac: Command+Option+period. Windows: Ctrl+Alt+period.</span></dd></div><div><dt>Plan</dt><dd>Enter /plan with the outcome, then review the plan. <span>Mac: Command+period opens the agent picker. Windows: Ctrl+period.</span></dd></div></dl><p class="small muted">If your default is queue, Enter and Option/Alt+Enter swap meanings. Stop does not undo completed actions or cancel every pending follow-up; inspect those separately.</p><details><summary>Before using Send Later</summary><p>Choose a delay or a date and time, and check this device's time zone. A preset schedules immediately. Local Send Later needs an awake computer and an available host; it does not wake your laptop.</p><p>Use Cancel Schedule and confirm the pending entry is gone, or manage it in Automations. Turning off the setting does not cancel accepted requests. If you're unsure a schedule was created, check before retrying. Scheduled runs can use credits and act later with the session's permissions.</p></details>${docs([['Queue, steer and stop', DOCS.chat], ['Review and edit requests', DOCS.review], ['Model picker', DOCS.models], ['Automation requirements', DOCS.automations]])}</section>
<section id="spending"><h2>Keep spending a choice</h2><p>The workshop files are free. AI requests use your account's credits. Input, output, cached input and cache writes can all count; parallel sessions, retries and scheduled runs can use more.</p><ol><li>On GitHub, open <strong>Settings > Billing &amp; licensing > Budgets and alerts</strong>.</li><li>Review a <strong>Bundled AI credits</strong> budget of <strong>$0</strong>, with <strong>Stop usage when budget limit is reached</strong> selected if you do not want paid AI-credit overage. An alert alone does not stop usage.</li><li>Check your usage in Billing &amp; licensing. Open <strong>Licensing</strong> to review your plan and renewal date. The workshop code's redemption, card and renewal terms are still being confirmed.</li></ol><div class="note"><p>That budget does not cancel a subscription renewal, cover provider API-key bills or cap separate Cloud compute, memory and storage. Check those separately before any Cloud work. Keep workshop requests routed through Copilot; you do not need your own provider key.</p></div><p>Stop work and review budgets if you reach your intended limit. Reducing a budget or canceling a plan does not erase charges already incurred. Enabling the two settings costs nothing by itself; sending or scheduling work can use credits.</p>${docs([['Manage budgets', DOCS.budget], ['View usage', DOCS.usage], ['Plan and renewal', DOCS.plan], ['Separate Cloud billing', DOCS.cloudBilling]])}</section>
<section id="public"><h2>GitHub Pages is public</h2><p>Publishing a ${term('github-pages', 'GitHub Pages')} site exposes its content to the internet. On a personal GitHub Free account, the repository used for Pages must also be public.</p><p>Before you publish, check the files, screenshots and history for names, personal information, client work, keys and private links. Deleting a file afterward does not remove copies other people may have saved.</p><p>You can unpublish Pages in the repository settings, but that cannot recall shared copies. Nothing in tonight's draft guide publishes automatically.</p>${docs([['Create a GitHub Pages site', DOCS.pages]])}</section>
`);

const TASKS = [
  { id: 'practice-brief', short: 'Practice brief', title: 'Read the fictional practice brief', input: 'The practice brief is still being written. It will describe a fictional learning problem and the changes to explore, not Skola\'s roadmap or real customer research.', prompt: 'Read the supplied fictional practice brief for my fork of Skola. Summarize the goal, the task someone should complete and what must stay unchanged. Keep it labeled as practice material, not the maintainer\'s roadmap. List missing decisions instead of inventing requirements. Do not edit code yet.', see: 'A shared reason for the redesign and feature. The brief itself is still a placeholder.', checkpoint: 'Can you name the fictional task and the result we will check?', fallback: 'Do not invent a brief if the checked one is not ready. Ask a host which practice input to use.', further: 'Keep practice findings and any later real observations clearly separate.' },
  { id: 'settings-controls', short: 'Settings and controls', title: '6:10 to 6:20: settings and controls', input: 'VS Code Insiders, the checked two-key snippet and a personal GitHub sign-in.', prompt: 'Help me understand the workshop\'s checked settings and chat controls. Do not edit my settings or change permissions. Explain queue versus steer, Stop versus Stop and Send, and how to cancel a Send Later request. Then wait while I try the controls with the host.', see: 'Your own backed-up settings merge and a small controls rehearsal. The snippet does not turn on broad approvals.', checkpoint: 'Can you queue a next request, steer a correction and stop a task without assuming Stop undoes completed work?', fallback: 'Use the labeled menu actions and ask for help if your controls differ. Do not keep pasting settings to force an unavailable feature.', further: 'Use the Get ready reference for Mac and Windows shortcuts and the clean-account caveat.' },
  { id: 'fork-and-clone', short: 'Folder and fork', title: 'Make a folder and clone your fork', input: 'Start in VS Code. Use your personal GitHub account, Git and Node LTS. The offline workshop prep is still being checked.', prompt: 'Help me create my own fork of h16nning/skola, then make a local project folder and clone my fork from VS Code. Show my account, the fork URL and the destination folder before changing anything. Use approvals. Do not open PRs, issues or comments on the original project. Do not launch Skola or contact its cloud-sync service until the checked offline workshop prep has been applied. Do not sign in to Skola.', see: 'A local working copy whose GitHub owner is you. We use React, Vite, Mantine, Dexie and FSRS as the project\'s existing stack, not a replacement mockup.', checkpoint: 'Check the fork owner and local folder. Cloud sync must be disabled before the app runs.', fallback: 'Pause at setup if Git, Node or the safe prep is missing. Do not run an unprepared copy against the maintainer\'s sync service.', further: 'Install the project packages only after reviewing the pinned npx/pnpm command on Get ready.' },
  { id: 'quick-redesign', short: 'Quick redesign', title: 'Make a quick, impactful redesign', input: 'Your offline-prepared fork of Skola and the fictional practice brief.', prompt: 'Use Skola\'s existing code and components to make the one redesign agreed in our fictional practice brief. Keep the real interaction working and leave unrelated screens alone. Do not replace the app with a screenshot recreation. Check the result at desktop and phone width. Keep cloud sync disabled, do not sign in, and do not push or publish.', see: 'A visible improvement in the real flashcard app, in your own fork.', checkpoint: 'Try the interaction yourself and explain which part changed.', fallback: 'Keep the unfinished attempt in its own branch or folder. The next task will have a prepared starting point.', further: 'Use the later Mark Up step for focused visual feedback on the actual interface.' },
  { id: 'useful-feature', short: 'Useful feature', title: 'Add a useful feature', input: 'A fresh prepared starting point and the feature scope from the practice brief. It does not depend on the redesign finishing.', prompt: 'Plan the feature agreed in the fictional brief for my fork of Skola. Identify the existing files, local data flow and checks. After I approve the scope, implement it without enabling cloud sync or changing unrelated behavior. Test the main path, an empty state and a failure case where relevant. Do not install extra packages or open a PR without approval; any PR must target my own fork.', see: 'A real feature in the existing codebase. The exact feature is still being chosen.', checkpoint: 'Try it yourself. Which states work, and what is still incomplete?', fallback: 'Save the partial result and its open questions, then use the prepared baseline for alternatives.', further: 'Ask a second model to review the change, then reproduce its findings yourself.' },
  { id: 'three-designs', short: 'Parallel alternatives', title: 'Explore visual alternatives in parallel', input: 'A saved Skola baseline in separate folders or worktrees. Review the permission change before choosing worktrees.', prompt: 'Explore exactly three different layouts for this screen in my fork of Skola. Use the existing components and keep the same content and working interaction. Give each direction its own folder or branch and do not let agents edit shared files. Preserve the baseline and cloud-sync-off prep. Show the real results for comparison and test desktop and phone widths. Do not publish, merge or contact upstream.', see: 'Three alternatives with meaningful changes in layout or hierarchy.', checkpoint: 'Try the same action in each and choose one decision you would keep.', fallback: 'If you work through directions one at a time, label it a sequential fallback rather than a parallel run.', further: 'Bring the chosen result back to a clean branch and check it again.' },
  { id: 'markup-feedback', short: 'Mark Up feedback', title: 'Mark up a screenshot', input: 'A screenshot of your working redesign in the current chat input, before it is sent.', prompt: 'Use my marked-up screenshot to change the actual design in my fork of Skola. First confirm the marks you can see. Keep unrelated behavior and the offline prep unchanged. Do not replace the real app with an image or enable cloud sync. Open the updated interface and check the change.', see: 'Your visual feedback applied to the real code. Use the image\'s Mark Up action, then Done and Send.', checkpoint: 'Compare the live interface with your marked image. Can you see the change you meant?', fallback: 'Use the documented OS editor if native Mark Up is unavailable. Escape applies markup; it is not discard.', further: 'Arrows and crop are supported. Moving original screenshot pieces is not a checked native capability, and manual markup is not Computer Use.' },
  { id: 'demo-video', short: 'Narrated video', title: 'Make a narrated demo while another task runs', input: 'A completed, saved copy of your fork or a prepared working version. Keep parallel edits away from the copy being recorded.', prompt: 'Plan a short narrated video showing one complete flow in my fork of Skola. Identify the recording route, supported voice, permissions and costs first. After I approve the setup, record the real interface and save a playable narrated video. Play it back and check it. Keep cloud sync disabled. Do not substitute screenshots, a silent clip or an animation, install tools without approval, or publish.', see: 'A real narrated video on your laptop. Start it, do an independent task, then return to review the result.', checkpoint: 'Play the file outside the chat. Can you see the full task and hear the narration?', fallback: 'Ask for help if recording or narration is unavailable. A screenshot sequence is not the video result.', further: 'Credit Skola and state what you changed when you use the demo in a portfolio.' },
  { id: 'desktop-task', short: 'Computer Use', title: 'Use the redesigned app for a real task', input: 'Your offline-prepared redesigned app, a task from the fictional brief, and your own Computer Use permissions.', prompt: 'Use Computer Use to carry out the agreed practice task in my redesigned fork of Skola. Confirm the app and scope before acting. Use only the fictional practice data. Do not sign in, enable sync, open private material, send, publish or contact the original project. Show what happened in the real app and stop. If the task is unsupported, explain that without claiming a different tool was Computer Use.', see: 'The agent using your actual redesigned app to complete the agreed task. The precise task is still being chosen.', checkpoint: 'Inspect the real app result. Did the agent stay within the task and approved access?', fallback: 'Leave permissions unchanged if setup is unclear. A manual action is a fallback, not a Computer Use result.', further: 'Use /computer off and revoke OS access afterward if you no longer want it.' },
  { id: 'taste-automation', short: 'Taste automation', title: 'Try Keep my taste current', input: 'The draft plugin template and a separate ordinary folder of notes and examples you select. The room\'s source notes are still being chosen.', prompt: 'Preview Keep my taste current using only the notes and examples I explicitly choose in this folder. Show its inputs, draft output, permissions, costs and stop controls. Keep the trigger Manual and ask before Run now. Do not enable a recurring schedule, read other folders or change personal skills. Let me review the first draft.', see: 'A personal taste draft from an explicitly approved first run. Installation alone creates no schedule or skill.', checkpoint: 'Can you inspect the selected sources and draft before adopting it?', fallback: 'With no notes, stop at the note format. Do not mine private messages or create a substitute recurring job.', further: 'This stays in an ordinary folder with Manual permissions. Weekly scheduling and installing a personal skill are separate choices.' },
  { id: 'share-it', short: 'Publish your fork', title: 'Last: publish your version on GitHub Pages', input: 'Your reviewed fork, the license and notices, and the checked Skola publishing recipe. Exact fix steps are not ready yet.', prompt: 'Review my fork of Skola for publication, but do not deploy yet. Keep AGPL-3.0 notices, add a dated modified-by note and link the live app to my corresponding source. Verify cloud sync is disabled and no sign-in is used. Use only the checked workshop Pages recipe; do not invent configuration fixes. Check that any PR targets my own fork, never h16nning/skola. After I explicitly approve publication, verify the live app and give me its link beside my repo link.', see: 'My fork of Skola, with a working link such as username.github.io/skola and a source link. Publishing is the last guided step in this draft.', checkpoint: 'Open the live URL in a fresh browser and on your phone. Check the real task, offline prep, notices and source link.', fallback: 'Wait for the checked recipe if deployment is not ready. Do not reuse the upstream domain or present a broken or fake static page as the real app.', further: 'Describe your own redesign or feature in the portfolio, credit Skola, and keep it clear that this is your fork.' },
];
const tonight = hero('Thursday, together', 'Tonight', 'Make a redesign and a feature in your own fork of Skola, then share a narrated demo, repo link and working site.') + layout([
  ['The project and safety', 'before'], ['Controls and permissions', 'controls'], ...TASKS.map((t, i) => [`${i + 1}. ${t.short}`, t.id]), ['Free work in pairs', 'free-work'],
], `${draft("We'll finalize tonight's steps by Wednesday. The practice brief and detailed run sheet are still open. Settings and controls are 6:10 to 6:20, with publishing last.")}
<section id="before"><h2>Your fork of Skola</h2><p><a href="${DOCS.skola}">Skola</a> is an open-source, local-first flashcard app by <strong>h16nning and contributors</strong>, licensed under <a href="${DOCS.skolaLicense}">AGPL-3.0</a>. This workshop is not affiliated with or endorsed by the Skola project.</p><p>Keep its license and notices. Present the result as <strong>my fork of Skola</strong>, with a clear account of your own redesign or feature.</p><div class="note"><p><strong>Upstream stays untouched.</strong> No PRs, issues, comments or stars go to the original project. Every PR targets your own fork; check the base repository because fork PRs can default to upstream.</p><p><strong>Cloud sync must be off. Nobody signs in to Skola.</strong> Do not launch an unprepared copy. The checked workshop prep will make sync inert before we use localhost or Pages.</p></div><p class="small muted">The prepared kit and real Skola screenshots are coming. We will use screenshots from the actual checked app, not a recreation of its UI.</p><p>Each task gets a prepared starting point so an unfinished earlier task does not block the next one. Recording uses a saved copy while another independent task runs.</p></section>
<section id="controls"><h2>Start with approvals</h2>${checked}<p>Start in Interactive mode with Manual permissions. Once a task is bounded and its tools are understood, we will show what Autopilot and Allow all permit before anyone chooses them. New Worktree sessions always use Allow all; none of these choices is a sandbox.</p><p>The taste automation stays in an ordinary folder with Manual permissions. Publishing and any PR still need your explicit approval and must stay in your own fork.</p><p><a href="${u('get-ready/#controls')}">Open the controls card</a> for Send, queue, steer, stop, Send Later, edit and resend, images, model selection, Plan, and the Mac and Windows shortcuts. <a href="${u('get-ready/#screenshot-markup')}">Mark Up instructions</a> explain the image feedback loop.</p></section>
${TASKS.map((t, i) => `<section id="${t.id}"><div class="step-heading"><span class="step-number">${String(i + 1).padStart(2, '0')}</span><h2>${t.title}</h2></div><p class="small muted">Starting point</p><p>${t.input}</p>${promptBlock(t.id + '-prompt', t.prompt)}<h3>What you should see</h3><p>${t.see}</p><div class="checkpoint"><h3>Checkpoint</h3><p>${t.checkpoint}</p></div><details><summary>If you're still waiting</summary><p>${t.fallback}</p></details><details><summary>Go further</summary><p>${t.further}</p></details></section>`).join('')}
<section id="free-work"><h2>7:10 PM: make it yours</h2><p>Pair up and improve one small result. Use only fictional notes and practice data; none of it is evidence about real Skola users.</p><div class="path-grid"><div><h3>New to this</h3><ul><li>Finish a redesign or feature in your fork.</li><li>Ask a partner to try it without coaching.</li><li>Use one observation to improve the result.</li></ul></div><div><h3>Already use agents</h3><ul><li>Apply the same workflow to a personal project.</li><li>Compare a second model's review with your own checks.</li><li>Prepare your own-fork PR, repo link, narrated demo and live site.</li></ul></div></div><p>At 8:00, volunteers can show a result and one decision. The take-home includes fictional research synthesis and advanced Cloud and overnight planning; those are not permission to start extra services or send anything upstream.</p></section>`);

const words = hero('A reference, not homework', 'Words to know', 'You do not need to learn these all at once. Come back when a word shows up in the thing you are trying.') + layout(WORD_GROUPS.map(g => [g.title, g.id]), WORD_GROUPS.map(g => `<section id="${g.id}"><h2>${g.title}</h2><p class="muted">${g.intro}</p><nav class="word-jump" aria-label="${g.title} terms">${g.terms.map(([id, name]) => `<a href="#${id}">${name}</a>`).join('')}</nav><dl class="glossary">${g.terms.map(([id, name, text, url]) => `<div class="term" id="${id}"><dt><a href="#${id}">${name}</a></dt><dd><p>${esc(text)}</p><a href="${url}">Official docs<span class="sr-only"> for ${name}</span> ↗</a></dd></div>`).join('')}</dl></section>`).join(''));

const keep = hero('After the workshop', 'Keep going', 'Come back to a task, try it on your own project, or take it a little further. You can work through these in any order.') + `<div class="wrap">
<div id="course-locked" class="course-intro"><section aria-labelledby="inside"><p class="eyebrow">The take-home</p><h2 id="inside" class="module-title">Eleven places to start</h2><p class="muted">A first pass of the course is here. The workshop examples and recording instructions are still being finalized.</p><ol class="module-preview">${COURSE.map(m => `<li>${m.title}</li>`).join('')}</ol></section><section class="lock-card" aria-labelledby="open-course"><span class="badge">For workshop attendees</span><h2 id="open-course" style="margin-top:18px">Open your take-home</h2><p>Use the password on your welcome sheet. The lessons are encrypted; there is no password or plaintext course in the public repository.</p><form class="lock-form" id="lock-form" data-payload="${u('keep-going/course.json')}"><label for="course-password">Workshop password</label><input id="course-password" type="password" required autocomplete="current-password" autocapitalize="none" spellcheck="false" aria-describedby="lock-status remember-help"><label class="remember"><input type="checkbox" id="remember-course"><span>Remember on this device</span></label><p class="small muted" id="remember-help">Only on a device you own. Saved access stays here until you choose Forget access.</p><button class="button" type="submit">Open the take-home</button><p class="lock-status" id="lock-status" role="status" aria-live="polite"></p></form><noscript><p>JavaScript is needed to open the encrypted course. The public setup and glossary work without it.</p></noscript></section></div>
<section id="course-open" hidden aria-labelledby="course-heading"><div class="course-open-bar"><div><h2 id="course-heading" tabindex="-1">Your take-home</h2><p id="course-access-status"></p></div><button class="button secondary" id="forget-course" type="button">Forget access</button></div><div id="course-content"></div></section></div>`;

const skills = hero('An optional next step', 'Skills', 'Reusable instructions for the kinds of work we are trying together. Read what a skill can do before giving it a task.') + layout([
  ['What is included', 'included'], ['What it installs', 'installs'], ['VS Code', 'vscode'], ['Copilot CLI', 'cli'], ['Remove it', 'remove'],
], `${draft('The design-workshop plugin is on a review branch, not the published main branch. The install steps below are for after its release is approved. The workshop setup is still being checked.')}
<section id="included"><h2>Nine workflows to try</h2><p>A ${term('skills', 'skill')} is guidance an agent can use for a task. A ${term('plugins', 'plugin')} packages related skills so you can install them together. This is a draft set, not a copy of anyone's personal setup.</p><dl class="skills-list"><div><dt><code>workshop-setup</code></dt><dd>Check your laptop and explain proposed changes before doing them.</dd></div><div><dt><code>variations</code></dt><dd>Explore different directions in separate folders or worktrees, with today's version for comparison.</dd></div><div><dt><code>demo-walkthrough</code></dt><dd>Rehearse a real flow, then record with a verified recorder or capture the screenshots you asked for. Recording needs checked tooling.</dd></div><div><dt><code>prototypes</code></dt><dd>Build in your own repo on a branch and prepare a before-and-after pull request.</dd></div><div><dt><code>pair-test</code></dt><dd>Plan a short test with a partner and keep real observations.</dd></div><div><dt><code>publish-pages</code></dt><dd>Review what would be public, then publish only after you approve.</dd></div><div><dt><code>taste</code></dt><dd>Create a taste draft from selected workspace notes through the opt-in automation, then propose updates for review.</dd></div><div><dt><code>overnight-plan</code></dt><dd>Plan bounded work with checkpoints and a clear stop condition.</dd></div><div><dt><code>job-search</code></dt><dd>Draft job-search material for you to review and send yourself.</dd></div></dl><p class="small muted" style="margin-top:20px">The scope may change before release. Real recording and narration still need clean personal-laptop rehearsals. Voice can follow the same idea later; no voice template is included.</p></section>
<section id="installs"><h2>What it installs</h2><p>The draft plugin adds instructions and automation templates, including <strong>Keep my taste current</strong>. That template is intended to build a personal taste skill from references you choose. The draft starts with a Manual trigger and an explicitly chosen Run now before any optional weekly schedule. Review the selected sources, output and cost first. The exact workshop flow is still being checked. Installing a template does not enable a recurring job.</p><p>It includes instructions, references, an inert optional recording helper, and two opt-in automation templates. It bundles no hooks or MCP servers and does not install the helper's dependencies. It does not silently change settings, turn on background work or grant broader permissions. A skill may suggest a setup change; review the action before approving it.</p><p>Skills are instructions, not a sandbox. Normal permissions still matter, and AI requests still use credits. Nothing is sent or published unless you choose to do that.</p>${docs([['How plugins work', DOCS.plugins], ['Permissions', DOCS.permissions]])}</section>
<section id="vscode"><h2>Install in VS Code, after release</h2><ol><li>Open the Copilot harness in VS Code Insiders and run <strong>Chat: Open Customizations</strong>.</li><li>In <strong>Browse</strong>, open the source menu, then <strong>Configure Marketplaces > Add Marketplace</strong>. After release, enter <code>eli-w-king/ai-first-design-workshop</code>.</li><li>Select <strong>design-workshop</strong>, review the README and included skills, then choose <strong>Install</strong> and approve the trust prompt only if you agree.</li></ol><p>If that Browse interface is unavailable, use <strong>Plugins > Browse Marketplace</strong> where offered, or the documented CLI route below. Do not invent settings to force the install.</p><p>The release will use the <code>design-workshop</code> plugin in <code>eli-w-king/ai-first-design-workshop</code>. This link is shown as text until the plugin is available:</p>${promptBlock('plugin-link', 'vscode-insiders://chat-plugin/install?source=eli-w-king%2Fai-first-design-workshop&plugin=design-workshop', 'After release: install link')}<p>After installing, start a fresh session and check that all nine skills appear. Try <em>check my setup</em> first, then inspect the proposed actions before accepting changes.</p>${docs([['Install and review plugins in VS Code', DOCS.plugins]])}</section>
<section id="cli"><h2>Install in Copilot CLI, after release</h2><p>This is optional. If you already use Copilot CLI, add the workshop marketplace and install the named plugin:</p>${promptBlock('plugin-cli', 'copilot plugin marketplace add eli-w-king/ai-first-design-workshop\ncopilot plugin install design-workshop@ai-first-design-workshop\ncopilot plugin list', 'After release: terminal commands')}<p>The first command registers a catalog. The second downloads the plugin. The third lets you confirm what is installed. Review the plugin contents before you use it; this page does not install anything.</p><p>If you do not have the CLI, you can stay in VS Code. Installing another client is not required for the workshop.</p>${docs([['Copilot CLI plugin commands', DOCS.cliPlugins], ['Optional CLI installation', DOCS.cliInstall]])}</section>
<section id="remove"><h2>Remove it when you're done</h2><p>In VS Code, run <strong>Chat: Open Customizations</strong>, open <strong>Plugins</strong>, choose <strong>design-workshop</strong>, then <strong>Uninstall</strong>.</p><p>If you installed it through Copilot CLI, use:</p>${promptBlock('plugin-remove', 'copilot plugin uninstall design-workshop@ai-first-design-workshop\ncopilot plugin marketplace remove ai-first-design-workshop', 'Terminal commands')}<p>Removing the plugin does not undo files you made, settings you separately approved, or automations you deliberately enabled. Stop and remove those separately if you no longer want them.</p><p><a href="${u('keep-going/')}">The take-home</a> explains the taste automation, a short mention of taste and voice skills, and what connectors, MCP and hooks can access. Advanced overnight work has its own section.</p></section>`);

const missing = hero('Page not found', "Let's get you back.", 'This page may have moved. The workshop guide and setup checks are still here.') + `<div class="wrap" style="padding-bottom:100px"><div class="actions"><a class="button" href="${u('')}">Go to the home page</a><a class="text-link" href="${u('tonight/')}">Open tonight's guide →</a></div></div>`;

